 		});

+		// Recast reprints a logical node without the parentheses that separated a
+		// `??` from an `&&` or `||` operand, e.g. `(a && b) ?? c` becomes
+		// `a && b ?? c`, which is a syntax error. Keep those parentheses explicit.
+		visit(ast, {
+			visitLogicalExpression(path) {
+				this.traverse(path);
+
+				const { node } = path;
+				const needsParens = (child: ExpressionKind): boolean =>
+					child.type === 'LogicalExpression' &&
+					(node.operator === '??') !== (child.operator === '??');
+
+				if (needsParens(node.left)) {
+					node.left = types.builders.parenthesizedExpression(node.left);
+				}
+				if (needsParens(node.right)) {
+					node.right = types.builders.parenthesizedExpression(node.right);
+				}
+			},
+		});
+
 		return print(ast);
 	} catch (e) {
 		return;
